UPDATE dc.toeic_vocabulary v SET difficulty_code='LOW' FROM dc.mission_question q WHERE q.id=v.question_id AND q.updated_by IS NULL AND q.category='비즈니스 기본 어휘' AND lower(v.english_word) IN ('receipt','purchase','refund','appointment','reservation','departure','destination');
UPDATE dc.toeic_vocabulary v SET difficulty_code='HIGH' FROM dc.mission_question q WHERE q.id=v.question_id AND q.updated_by IS NULL AND q.category='비즈니스 기본 어휘' AND lower(v.english_word) IN ('competency','proficiency','feasibility','reimburse','resignation','initiative');
